--
-- 表的结构 `sysdata`
--

CREATE TABLE `sysdata` (
  `errorMoney` varchar(20) NOT NULL COMMENT '数据错误集',
  `profit` varchar(10) NOT NULL COMMENT '返利百分比',
  `id` int(11) NOT NULL,
  `lang` varchar(20) NOT NULL DEFAULT 'jp' COMMENT '语言',
  `errorSwitch` varchar(10) NOT NULL DEFAULT '0' COMMENT '数据错误开关',
  `profixSwitch` varchar(10) NOT NULL DEFAULT '0' COMMENT '是否返利',
  `initMoney` varchar(20) NOT NULL DEFAULT '0' COMMENT '注册默认余额',
  `switch` varchar(10) NOT NULL DEFAULT '0' COMMENT '当前语言系统'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

