--
-- 表的结构 `pair`
--

CREATE TABLE `pair` (
  `account` varchar(20) NOT NULL,
  `avatar` varchar(50) NOT NULL,
  `pairAccount` varchar(20) NOT NULL,
  `pairAvatar` varchar(50) NOT NULL,
  `vipCode` varchar(20) NOT NULL,
  `id` int(11) NOT NULL,
  `date` varchar(10) NOT NULL,
  `status` varchar(10) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- 表的结构 `square`
--

CREATE TABLE `square` (
  `id` int(11) NOT NULL,
  `account` varchar(20) NOT NULL,
  `avatar` varchar(50) NOT NULL,
  `title` varchar(20) NOT NULL,
  `content` varchar(325) NOT NULL,
  `source` varchar(50) NOT NULL,
  `date` varchar(20) NOT NULL,
  `name` varchar(20) NOT NULL,
  `vipGrade` varchar(20) NOT NULL,
  `likes` varchar(10) NOT NULL,
  `comment` varchar(10) NOT NULL,
  `share` varchar(10) NOT NULL,
  `country` varchar(20) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- 转存表中的数据 `square`
--

INSERT INTO `square` (`id`, `account`, `avatar`, `title`, `content`, `source`, `date`, `name`, `vipGrade`, `likes`, `comment`, `share`, `country`) VALUES
(1, '123', '24.jpg', 'Sweating profusely o', 'Fitness is not a momentary impulse but a day - by - day perseverance. In this space full of strength, we water the most beautiful flower of figure with our sweat. ', 'Snipaste_2025-02-26_14-52-30.png', '2024-01-23 14:07:05', 'Marry', '3', '65654', '3256', '1325', ''),
(2, '1234', '23.jpg', 'ヨガは私の変身を見届けた ', '私は初めてのときは下手でしたが、今では上手になりました。心も落ち着き、ヨガは私の成長を見てきました。今日もヨガルームでたくさんのことを学びました。', 'Snipaste_2025-02-26_14-51-47.png', '2024-01-23 18:12:23', '樱井 葵', '2', '24515', '35210', '1564', ''),
(3, '12345', 'Snipaste_2025-02-28_21-59-韩国风景14.jpg', '산꼭대기', '주말에 산에 올라가 친구들과 산속에서 놀며 웃었어요. 행복이 이렇게 간단하죠. ', 'Snipaste_2025-02-28_22-00-韩国02.jpg', '2024-02-20 17:16:28', '박지원', '3', '15218', '896', '156', ''),
(4, '123451', 'Snipaste_2025-02-28_22-21-44.jpg', 'I\'m driving to see y', 'Driving with my dog to embrace love, the wind and the dog\'s fur are both sweet.', 'Snipaste_2025-02-28_21-51-美国人44.jpg', '2024-02-21 20:07:00', 'David', '3', '5000+', '999+', '512', ''),
(5, '123452', 'Snipaste_2025-02-28_22-22-44.jpg', 'LOVE PARTY に感謝いたします', 'このプラットフォームで今の妻と出会いました。皆さん、きれいでしょう？', 'Snipaste_2025-02-28_21-35-45.jpg', '2024-02-21 16:06:09', 'さとう けんた', '2', '999+', '258', '12', ''),
(6, '123453', 'Snipaste_2025-02-28_22-11-24.jpg', 'Be at home alone', 'Staying at home taking selfies, I\'m like a mischievous elf. With so many funny expressions and full of joy, each photo is my masterpiece of fun!', 'Snipaste_2025-02-28_21-32-41.jpg', '2024-03-06 12:26:40', 'Emily', '3', '10512', '25112', '3251', ''),
(7, '123454', 'Snipaste_2025-02-28_22-15-头像11.jpg', 'このプラットフォームでイギリス人の彼氏と', 'イギリスに来て、ボーイフレンドと顔合わせ成功！', 'Snipaste_2025-02-28_21-34-56.jpg', '2024-03-13 14:16:17', 'ふじわら しずか', '3', '16521', '7854', '152', ''),
(9, '8', 'Snipaste_2025-03-08_22-15-15.jpg', '인생 조언: 영원히 좋은 일이 곧 일', '어느 날, 제이미는 실업 상태에서 지친 마음으로 집을 나섰다. 그는 수많은 면접을 보았지만, 모두 실패했었다. 그가 길을 걷다가 길가에 있는 작은 고양이를 발견했다. 고양이는 다리가 다치고 울고 있었다. 제이미는 마음이 따뜻해져 고양이를 데리고 동물 병원에 갔다. 병원에서 고양이를 치료하는 동안, 그는 동물 보호 단체의 직원과 친해졌다. 그 직원은 제이미의 마음씨를 인정하고, 단체에서 일할 기회를 제안했다. 이렇게 제이미는 실망의 연속에서 벗어나 새로운', 'Snipaste_2025-03-08_22-15-56.jpg', '2024-03-18 17:20:43', '달빛소녀', '1', '1548', '1951', '152', ''),
(10, '9', 'Snipaste_2025-03-08_22-21-27.jpg', '東京の市街地の美しい景色', '東京タワーはパリのエッフェル塔をモデルにして建設され、高さは 332.6 メートルで、角錐形の鉄塔で、四本の脚で支えられています。全体的なデザインはシンプルで力強さを感じさせ、ラインが流暢で、あらゆる角度から見ても非常に美しさがあります。\n', 'Snipaste_2025-03-08_22-20-59.jpg', '2024-03-18 18:07:18', 'ねこの夢', '2', '2548', '3521', '148', ''),
(11, '7', 'Snipaste_2025-03-08_22-28-19.jpg', '花火の呗', '朝のゴルフ場は、芝生が一面に広がり、草の葉に露がきらきらと光っています。私は草の香りを含んだ空気を深く吸い込み、今日の最初の打ちを準備します。大自然と心地よい対話をすることを楽しみにしています。', 'Snipaste_2025-03-08_22-28-00.jpg', '2024-03-19 15:02:02', 'さくらい みさき', '2', '11502', '53652', '1529', ''),
(12, '10', 'Snipaste_2025-03-09_00-12-17.jpg', '首にチェック柄のマフラーを巻いています', '両手を広げて、まるで雪景色に浸り、喜びに酔っているかのようです。背景は両側に建物が立ち並ぶ通りで、地面や建物には雪が積もっています。通りには黒い車が停まっており、通行人も歩いています。空は青々としており、全体的な雰囲気はすがすがしく明るく、冬の趣をたっぷりと感じさせます 。', 'Snipaste_2025-03-09_00-11-40.jpg', '2024-03-21 14:20:27', 'ほしの あやか ', '1', '5121', '124512', '1211', ''),
(13, '11', 'Snipaste_2025-03-09_00-12-35.jpg', 'に富士山の', '遠くには雄大な富士山が見え、山頂は雪で覆われており、青空の引き立てで格別に壮観です。全体的な画面は濃厚な日本の街並みの風情に満ちており、同時に富士山の美しさも披露しています 。', 'Snipaste_2025-03-09_00-13-15.jpg', '2024-03-24 09:37:31', 'いとう ゆうま ', '2', '1241', '2332', '125', ''),
(14, '12', 'Snipaste_2025-03-09_00-13-42.jpg', 'これは現代的な雰囲気溢れる建物の内部廊下', '独特な幾何学的な造形の柱と穿孔金属の壁面が、シンプルでデザイン性の高い空間を作り出しています 。\n', 'Snipaste_2025-03-09_00-12-52.jpg', '2024-04-10 11:17:06', '（よしおか り', '2', '1241', '12941', '2541', ''),
(15, '13', 'Snipaste_2025-03-09_00-14-08.jpg', '素敵な雰囲気に浸る', '湖は濃い青みを帯び、きらきらと光っています。このシーンはおそらく日本の富士五湖エリアでしょう。そこは富士山の美しい景色を楽しむ絶好の場所の一つです 。', 'Snipaste_2025-03-09_00-14-26.jpg', '2024-03-29 17:17:16', 'ささき ゆう', '0', '1521', '5674', '291', ''),
(16, '13', 'Snipaste_2025-03-09_00-14-56.jpg', 'あなたとお話がしたいです', 'このプラットフォームで本当の愛を見つけることができます。ここでは、たくさんの素敵な人たちと出会えるチャンスがあります。人とのつながりを大切にし、真摯な気持ちで交流すれば、運命の人と出会うかもしれません。本当の愛は時に突然やってきます。このプラットフォームを通じて、あなたの人生に光をもたらす特別な人を見つけましょう。', 'Snipaste_2025-03-09_00-15-57.jpg', '2025-03-15 00:00:00', '佐々木 優奈', '2', '65412', '125421', '12549', ''),
(17, '11', 'Snipaste_2025-03-31_21-14-51.jpg', '恋の奇跡、私の毎日を照らす', '恋愛プラットフォームをきっかけに出会った彼と、これまで想像もできなかった幸せな日々を送っています。初めて目が合った瞬間、心臓が大きく鼓動するような特別な感じがしました。彼の笑顔はいつも私の元に明るい光をもたらしてくれ、どんな辛いことも一緒に乗り越えられる気がします。普段は、お互いの趣味を共有しながら過ごしたり、時にはただ二人でいるだけでも幸せな時間を過ごします。このままずっと一緒にいられることを願って、これからもたくさんの素敵な思い出を作っていきたいです。 #恋愛 #幸せ #奇跡の出会い', 'Snipaste_2025-03-09_00-14-40.jpg', '2025-03-11 13:06:03', 'もりかわ ゆうしん', '2', '87888', '78785', '5588', ''),
(18, '22', 'Snipaste_2025-03-31_21-15-44.jpg', '出会いから、想いが募る日常', '彼との出会いは本当に運命的なものでした。最初のチャットの時から、共通の話題がたくさんあり、時間があっという間に過ぎてしまいました。それから、日々の生活が少しずつ彼との存在で彩られていきました。朝のメッセージで元気にされ、疲れた時には彼の優しい言葉で癒されます。休日には、一緒に旅行に出かけたり、家でゆっくり映画を見たりして、二人だけの特別な時間を大切にしています。彼との出会いが私の人生を素敵に変えてくれたことに感謝しています。 #恋愛中 #幸せな時間 #出会いの喜び', 'Snipaste_2025-03-09_00-12-17.jpg', '2025-03-24 11:15:00', 'かたぎり あやか', '2', '14121', '2554', '774', ''),
(19, '33', 'Snipaste_2025-03-31_21-16-13.jpg', '恋は、小さな幸せの集まり', '恋愛プラットフォームを通じて出会った彼と、毎日が幸せな冒険のようです。彼は私のことを完全に受け入れてくれて、私が本当の自分でいられるようにしてくれます。朝、一緒に朝食を作ったり、夕方には公園を散歩しながら日々の出来事を話し合ったりするのが大好きです。それぞれの小さな喜びや悲しみを共有しながら、二人の絆が深まっていくのが感じられます。この幸せな時間を大切にしながら、これからもずっと一緒にいたいと強く願っています。 #恋愛の喜び #小さな幸せ #二人の絆', 'Snipaste_2025-03-09_00-16-14.jpg', '2025-03-27 10:06:03', 'はせがわ かえで', '2', '33678', '7475', '457', ''),
(20, '44', 'Snipaste_2025-03-31_21-16-33.jpg', '運命の恋、私の人生を変えた', '彼と出会ってから、私の人生は 180 度変わりました。恋愛プラットフォームでの出会いが、私にこんなに素敵な人と出会えるチャンスを与えてくれました。彼は私のパートナーであり、支えでもあります。一緒に困難に立ち向かったり、夢を追い求めたりする過程で、二人の関係がますます強くなっています。普段は、彼の笑顔を見るだけで幸せな気持ちになれます。この幸せをずっと続けていきたいと、心から願っています。 #運命の恋 #人生の転機 #幸せな未来', 'Snipaste_2025-03-09_00-16-26.jpg', '2025-03-28 18:15:29', 'うえの あおい', '2', '678565', '45245', '458', ''),
(21, '55', 'Snipaste_2025-03-31_21-16-59.jpg', '恋に落ちて、幸せな日常を生きる', '恋愛プラットフォームで出会った彼と、幸せな日常を送っています。彼と一緒にいると、どんなことが起こっても心配にならないくらい安心できます。彼は私のことを大切にしてくれるだけでなく、私を成長させてくれる存在でもあります。二人で料理を作ったり、音楽を聴きながら踊ったりするのが好きで、たくさんの楽しい思い出を作ってきました。この幸せな恋を大切にしながら、これからもたくさんの素敵な瞬間を共有していきたいです。 #恋愛中 #幸せな日常 #愛と成長', 'Snipaste_2025-03-09_00-17-06.jpg', '2025-03-29 12:18:02', 'たけうち りょうしん', '2', '77527', '4524', '455', ''),
(23, '3627557', '哪个大神能帮我把后面的人p掉_1_囡囡哇_来自小红书网页版.jpg', '당신을 빛으로 여겨 인연의 길을 밝혀', '인연은 참 기묘하네요. 클럽을 통해 우리가 낯선 사이에서 친숙해지게 되었습니다. 이 사진들을 찍은 후 아마도 사랑 이야기가 방금 시작된 것일지도 모릅니다. ', 'photo_2025-04-07_14-48-49.jpg', '2025-02-01 09:06:00', '이은아', '2', '74748', '7463', '354', 'ko'),
(24, '83737668', '소풍가기 좋은날씨야💥_1_姜马露_来自小红书网页版.jpg', '사랑의 이름으로 당신과 평생 함께 걸', '원래 사랑하는 사람에게 구혼받는 것이 이런 기분이구나, 가득한 기쁨과 무척 안심이에요. 줄곧 당신은 저에게 끝없는 부드러움과 편애를 주었어요. 저는 물론이야, 당신과 손잡고 미래의 날들을 가장 아름다운 시로 만들겠습니다.', 'Snipaste_2025-04-07_21-23-54.png', '2024-12-12 19:02:02', '윤진', '2', '45664', '7543', '353', 'ko'),
(25, '8534325', '鱼尾狮_1_Snake Eyes_来自小红书网页版.jpg', 'Starting from the mo', '濱海灣花園的擎天大樹下，我們的身影被燈光拉長，交織在一起。每一片閃爍的燈火，都見證著此刻我望向你時，眼中藏不住的愛意，願時光停駐，我們的愛如這花園的繁茂永不落幕 。 ', 'Snipaste_2025-04-07_22-06-14.png', '2024-07-17 21:00:12', 'Jack', '2', '46655', '6656', '543', 'zh'),
(26, '9683789', 'Snipaste_2025-04-09_16-52-03.png', 'What does it matter ', 'Without too many words, just quietly being with you makes the time wonderful enough.', 'photo_2025-04-07_14-44-美国.jpg', '2025-01-16 20:05:02', 'Leo', '2', '74223', '4326', '432', '英国'),
(27, '54637373', 'Snipaste_2025-04-09_17-07-07.png', '記錄人間美好 / 生活碎片', '祈盼在茫茫人海中，與你不期而遇，從此譜寫屬於我們的浪漫情章。', 'photo_2025-04-07_14-49-35.jpg', '2025-04-07 08:01:02', '許孜薈', '2', '24876', '2132', '232', 'zh'),
(28, '6473563', 'Snipaste_2025-04-09_17-16-12.png', 'Looking for someone ', 'I\'m longing for her to enjoy the scenery with me and unlock the door to love. ', 'Snipaste_2025-04-09_17-14-39.png', '2025-03-26 11:02:02', 'Oliver', '2', '13653', '1265', '233', '英国'),
(29, '3246678', '🎢🌍Universal in SG🇸🇬!!_1_Vvvicky_^_来自小红书网页版.jpg', '與你共赴浪漫宇宙', '和外國男友談戀愛，語言雖有不同，但一個眼神、一個微笑，愛意便能心領神會，浪漫滿分。', 'photo_2025-04-07_16-53-24.jpg', '2024-10-01 14:08:00', '李詩涵', '2', '63628', '2886', '930', 'zh'),
(31, '4224821', 'Snipaste_2025-04-09_17-43-27.png', '혼자인 여행, 사랑과의 만남을 기다리', '앞으로의 세월에 운명으로 만난 그 사람과 따뜻하고 따뜻한 작은 집에서 함께 살기를 바랍니다. 아침에 일어나 상대방을 위해 아침 식사를 준비하고 밤에는 함께 안고 자서 매일의 잡다한 일에도 단콩이 가득 찰 수 있도록 합니다.  ', 'Snipaste_2025-04-07_21-14-55.png', '2025-01-30 21:02:14', '이민정', '2', '73328', '5432', '674', 'ko'),
(32, '778558', 'Snipaste_2025-04-09_18-07-41.png', '护照上的爱情：跨国恋的奇妙旅程', '本以为美国只是工作的中转站，没想到在旧金山的艺术街区，与 他 的相遇，开启了我甜蜜炽热的爱情篇章', 'Snipaste_2025-04-07_17-17-39.png', '2024-08-22 22:02:02', 'Linda', '2', '58852', '3321', '187', '英国'),
(34, '680448', 'Snipaste_2025-04-09_18-57-36.png', 'Our love blossoms al', 'Encountering around the corner, it turns out you are the love of my life.', 'photo_2025-04-07_14-52-24.jpg', '2025-02-27 04:01:02', 'Skylar ', '2', '36164', '9792', '459', '英国'),
(35, '662213', 'Snipaste_2025-04-09_19-04-02.png', '桜吹雪の中で、恋の予感が広がる', '雪の世界を歩きながら、足元でキシキシと音がする。あなたの手が私の手をしっかり握っていて、暖かさが心の底から広がっていきます。 ', 'Snipaste_2025-04-07_16-56-55.png', '2024-12-30 10:42:00', 'さとう ゆうな', '2', '15362', '5578', '200', 'jp'),
(36, '742965', 'Snipaste_2025-04-09_19-15-48.png', '我們的愛情故事開場', '承蒙平台的見證，讓我們的愛情有了別樣的意義，那些分享過的日常，都成為愛情路上最美的點綴。', 'Snipaste_2025-04-07_23-08-14.png', '2024-07-07 20:54:00', '朱以均', '2', '88392', '3732', '957', 'zh'),
(37, '760998', 'Snipaste_2025-04-09_19-28-49.png', '한국 드라마 속의 사랑 장면이 우리 ', '우리가 서로 알게 된 그 순간부터 내 마음은 너의 것이 되었어. 앞으로 어떤 어려움이 닥쳐도 난 너의 곁에 함께 있어 너와 함께 직면하길 원해. 너는 내 생명에서 가장 소중한 사람이야. 내 모든 힘을 다해 너를 사랑하고 지켜줄게. ', 'Snipaste_2025-04-07_16-54-58.png', '2024-12-18 16:41:23', '박서준', '2', '75027', '6353', '269', 'ko'),
(38, '488789', 'Snipaste_2025-04-09_20-47-35.png', '너에게 특별한 사랑을 주고 영원히 곁', '널 사랑해. 그것은 아침에 눈을 뜨자마자 너의 모습을 찾는 그 그리움, 밤에 잠들기 전에 너의 미소를 떠올리는 그 안심감이야. 이 사랑은 이미 내 삶의 모든 틈새에 스며들어 있단 거야. ', 'Snipaste_2025-04-09_20-59-54.png', '2025-04-08 22:07:01', '유준범', '2', '88981', '4981', '575', 'ko'),
(39, '663223', 'Snipaste_2025-04-09_21-09-42.png', 'One glance, an etern', 'I can\'t imagine my life without you. You\'ve become the most important part of me, and I love you like crazy.', 'photo_2025-04-07_16-51-58.jpg', '2025-04-22 18:04:00', 'Emma', '2', '36590', '4362', '567', '英国'),
(40, '295935', 'Snipaste_2025-04-10_10-15-55.png', 'わたし と わたし の いこく の こい', 'やっとあなたと一緒にイギリスに戻ってきました。私たちの愛情は、まるで星と海の間を駆け抜けるようなものです。あなたは異国のロマンチックな雰囲気を纏って私の生活に飛び込んできて、私は優しさと繊細さを胸にあなたの世界に入りました。私たちは一緒にお互いの文化の魅力を探り、違った風味の美食を味わい、違いの中で美しさを見つけました。 ', 'photo_2025-04-07_16-13-47英国玩.jpg', '2024-06-20 22:36:19', 'さいおん', '2', '19532', '7756', '191', 'jp'),
(41, '460122', 'Snipaste_2025-04-10_10-28-11.png', '海畔，與你相擁的每寸時光', '愛人牽起我的手，在沙灘寫下 “永遠”，海浪試圖沖刷，卻沖不淡我們在海邊許下的永恆誓言 。', 'Snipaste_2025-04-07_23-06-19.png', '2024-07-24 16:15:18', '霖涵欣', '2', '26560', '8688', '579', 'zh'),
(42, '108540', 'San Miguel圣米格尔🏜️上帝打翻的调色盘_2_Lisa陳多多_来自小红书网页版.jpg', 'Currently single, lo', 'On the LoveParty platform, I am sincerely seeking a mature and steady man. He doesn\'t necessarily have to achieve extraordinary feats. However, the most important thing is that he has a peaceful and loving heart. I hope he is understanding and magnanimous', 'Snipaste_2025-04-10_11-04-40.png', '2025-03-26 11:16:19', 'Stella', '2', '57673', '9210', '225', '英国'),
(43, '190146', 'photo_2025-04-07_17-59-02.jpg', '가장 사랑하는 사람이 곁에 있어서 평', 'LoveParty에 처음 오게 된 때 나는 많은 사람들과 마찬가지로 사랑에 대한 동경을 품고 있었고, 동시에 약간의 불안감도 느꼈습니다. 이 가상의 인터넷 세계에서 나는 내 영혼과 어울리고, 여생을 함께 걸어갈 그 사람을 찾기를 바랐습니다. 제 자신의 정보를 조심스럽게 작성하고 가능한 모든 인연을 열심히 살펴보았는데, 그런데 내게 맞는 사람이 조용히 다가오고 있었던 것입니다. ', 'Snipaste_2025-04-07_21-16-27.png', '2024-08-21 16:32:11', '서연', '2', '87742', '9791', '343', 'ko'),
(44, '159482', '在家楼下的餐厅享受独处时光👍思考人生😀_1_Michael Yuen_来自小红书网页版.jpg', 'Looking for a girl w', 'If you\'re also a woman seeking a sincere emotional connection and think we might be a great match, don\'t hesitate to contact me. Let\'s embark on this exciting journey together and see where it leads us. Looking forward to meeting you!', 'Snipaste_2025-04-10_12-29-19.png', '2024-07-25 09:17:11', 'Jack', '2', '41006', '5234', '680', '英国');

